using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfig;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfig = CreateReportingConfiguration();
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(string scenarioName, EvaluationScenario scenario)
    {
        await using var session = await s_reportingConfig!.CreateScenarioRunAsync(scenarioName);

        var chatClient = session.GetChatClient();
        var messages = new List<ChatMessage>();

        foreach (var turn in scenario.Turns)
        {
            messages.Add(new ChatMessage(ChatRole.User, turn.Content));
        }

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await session.EvaluateAsync(messages, response);
    }

    private static IEnumerable<object[]> GetScenarios()
    {
        var scenarios = EvaluationScenario.LoadFromYaml(
            Path.Combine(AppContext.BaseDirectory, "evaluation.yml"));

        foreach (var scenario in scenarios)
        {
            yield return new object[] { scenario.Name, scenario };
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(AppContext.BaseDirectory, "evaluation-results"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClientFactory: CreateChatClient));
    }

    private static IChatClient CreateChatClient()
    {
        // Uses the same model configured in the AppHost for evaluation judging.
        // Set AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT is not set.");
        var apiKey = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("AZURE_OPENAI_API_KEY is not set.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(apiKey))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

using YamlDotNet.Serialization;
