using YamlDotNet.Serialization;
using YamlDotNet.Serialization.NamingConventions;

namespace MyApp.Evaluation;

public class EvaluationScenario
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<ScenarioTurn> Turns { get; set; } = new();
    public Dictionary<string, int> Expectations { get; set; } = new();

    public static List<EvaluationScenario> LoadFromYaml(string path)
    {
        var yaml = File.ReadAllText(path);
        var deserializer = new DeserializerBuilder()
            .WithNamingConvention(UnderscoredNamingConvention.Instance)
            .Build();

        var config = deserializer.Deserialize<EvaluationConfig>(yaml);
        return config.Scenarios;
    }

    public override string ToString() => Name;
}

public class ScenarioTurn
{
    public string Role { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
}

internal class EvaluationConfig
{
    public List<EvaluationScenario> Scenarios { get; set; } = new();
}

